namespace gui_forms {

// TypographySpecimen's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/typography_specimen.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The FontSpec the run is committed with; must be valid (std::invalid_argument).
template <typename Declaring>
struct TypographySpecimenFontCapability {
    PropertyCell<FontSpec, TypographySpecimenFontCapability<Declaring>> font{FontSpec{FontRole::content, 12.0, 400, false}};

    static void assign(TypographySpecimenFontCapability& capability, FontSpec incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.font), incoming);
        if (!capability.font.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.font));
    }
};

// The line under the run that names its font.
template <typename Declaring>
struct TypographySpecimenCaptionCapability {
    PropertyCell<std::string, TypographySpecimenCaptionCapability<Declaring>> caption{};

    static void assign(TypographySpecimenCaptionCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.caption), incoming);
        if (!capability.caption.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.caption));
    }
};

// Whether the line box, baseline and provider status are drawn.
template <typename Declaring>
struct TypographySpecimenDiagnosticsVisibleCapability {
    PropertyCell<bool, TypographySpecimenDiagnosticsVisibleCapability<Declaring>> diagnostics_visible{true};

    static void assign(TypographySpecimenDiagnosticsVisibleCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.diagnostics_visible), incoming);
        if (!capability.diagnostics_visible.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.diagnostics_visible));
    }
};

// Whether the run wraps at the specimen's width.
template <typename Declaring>
struct TypographySpecimenWrapTextCapability {
    PropertyCell<bool, TypographySpecimenWrapTextCapability<Declaring>> wrap_text{false};

    static void assign(TypographySpecimenWrapTextCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.wrap_text), incoming);
        if (!capability.wrap_text.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.wrap_text));
    }
};

// Every TypographySpecimen capability, in the order the declaring class takes them.
template <typename Declaring>
struct TypographySpecimenCapabilities : public TextCapability<Declaring>,
                                        public TypographySpecimenFontCapability<Declaring>,
                                        public TypographySpecimenCaptionCapability<Declaring>,
                                        public TypographySpecimenDiagnosticsVisibleCapability<Declaring>,
                                        public TypographySpecimenWrapTextCapability<Declaring> {};

} // namespace gui_forms
